/** Label -> the affliction rows carrying it. A label can appear in several
 *  pools; where two rows share a label they share a mechanic (asserted by the
 *  generator), so the first is as good as any. */
export const AFFLICTION_BY_LABEL = (() => {
  const m = new Map();
  for (const [key, a] of Object.entries(AFFLICTIONS)) {
    if (!m.has(a.label)) m.set(a.label, { ...a, key });
  }
  return m;
})();

/** Pools by source name, which is how a kit asks for one. */
export const AFFLICTION_POOL_BY_SOURCE = (() => {
  const m = new Map();
  for (const p of AFFLICTION_POOLS) {
    if (!m.has(p.source)) m.set(p.source, p);
  }
  return m;
})();

